def xor(v1, v2):
    return bytes(v1[i] ^ v2[i % len(v2)] for i in range(len(v1)))


if __name__ == "__main__":
    ciphertext = ""
    key = "636f6d7075746572656e6e65747765726b7365637572697479697374686562657374636f75727365"

    c_length = len(ciphertext)

    plaintext = xor(bytes.fromhex(ciphertext), bytes.fromhex(key))
    print(bytes.fromhex(plaintext.decode()).decode())

